class Contrasena {
  constructor(valor) {
    this.valor = valor; // Usa el setter automáticamente
  }

  get valor() {
    return this._valor;
  }

  set valor(v) {
    if (typeof v !== 'string') throw new Error('Debe ser string');
    if (v.length < 8) throw new Error('Mínimo 8 caracteres');
    if (!/[A-Z]/.test(v)) throw new Error('Debe tener una mayúscula');
    if (!/[0-9]/.test(v)) throw new Error('Debe tener un número');
    this._valor = v;
  }

  get esSegura() {
    return this._valor.length >= 12;
  }
}

const pwd = new Contrasena('MiPass123');
console.log(pwd.esSegura); // false (menos de 12)

try {
  new Contrasena('debil'); // Error: Mínimo 8 caracteres
} catch (e) {
  console.log(e.message);
}

class Fraccion {
  constructor(numerador, denominador) {
    this.numerador = numerador;
    this.denominador = denominador;
  }

  get valor() {
    return this.numerador / this.denominador;
  }

  get simplificada() {
    const mcd = (a, b) => b === 0 ? a : mcd(b, a % b);
    const divisor = mcd(Math.abs(this.numerador), Math.abs(this.denominador));
    return `${this.numerador / divisor}/${this.denominador / divisor}`;
  }

  toString() {
    return `${this.numerador}/${this.denominador}`;
  }
}

const f = new Fraccion(6, 8);
console.log(f.valor);        // 0.75
console.log(f.simplificada); // '3/4'
console.log(String(f));      // '6/8'

